# Helpers for reproduce.sh and fix.sh: Splunk reads and the arithmetic on them. Sourced, never run alone.
API="https://api.${SPLUNK_REALM}.signalfx.com"
STREAM="https://stream.${SPLUNK_REALM}.signalfx.com"
METRIC=db.client.operation.duration

series() { curl -sS --max-time 20 -G -H "X-SF-Token: $SPLUNK_API_TOKEN" "$API/v2/metrictimeseries" --data-urlencode "query=$1" --data-urlencode "limit=1000" 2>/dev/null; }
duration_series() { series "sf_metric:${METRIC}* AND deployment.environment:${LAB_NAME}"; }

# The Collector's main exporter decides how a histogram is stored, so its one setting is printed from the rendered
# config. Only this key is printed: the rest of the config stays out of the log.
exporter_config() {
  local relay
  relay=$(kubectl -n splunk get configmap splunk-otel-collector-otel-agent -o jsonpath='{.data.relay}' 2>/dev/null)
  [ -n "$relay" ] || { echo "  the Collector's rendered config could not be read"; return; }
  awk '/^  signalfx:$/ { on = 1; next } on && /^  [^ ]/ { on = 0 } on && /send_otlp_histograms/ { found = 1; print "  signalfx " $0 } END { if (!found) print "  signalfx send_otlp_histograms: not set, the chart default" }' <<<"$relay"
}

# The metric names exactly as Splunk stores them.
raw_names() { series "$1" | jq -r '[.results[]?.metric // empty] | unique | .[]' 2>/dev/null; }

# Cumulative CPU steal for the app node, as jiffies stolen and jiffies in total, from the node's /proc/stat.
cpu_stat() { kubectl -n demo exec "$1" -c app -- head -1 /proc/stat 2>/dev/null | awk '{ t = 0; for (i = 2; i <= NF; i++) t += $i; print $9, t }'; }

# SignalFlow answers as a stream of events, and each event's JSON spans several `data:` lines. This writes one
# {ts, le, value} line per point, and keeps the raw reply in signalflow.txt for the error message.
signalflow() {   # program, start ms, stop ms
  curl -sS --max-time 60 -X POST -H "X-SF-Token: $SPLUNK_API_TOKEN" -H "Content-Type: text/plain" --data-binary "$1" \
    "$STREAM/v2/signalflow/execute?start=$2&stop=$3&resolution=60000&immediate=true" 2>&1 | tee signalflow.txt |
    awk '/^event:/ { if (b != "") print e "\t" b; e = $2; b = ""; next }
         /^data:/  { sub(/^data: ?/, ""); b = b $0; next }
         END       { if (b != "") print e "\t" b }' |
    jq -Rcn 'reduce (inputs | split("\t") | {e: .[0], b: (.[1] | fromjson? // {})}) as $x ({ids: {}, out: []};
        if $x.e == "metadata" then .ids[$x.b.tsId] = ($x.b.properties.le // "all")
        elif $x.e == "data" then .ids as $ids | .out += [$x.b.data[]? | select(.value != null)
          | {ts: $x.b.logicalTimestampMs, le: ($ids[.tsId] // "all"), value: .value}]
        else . end) | .out[]' 2>/dev/null
}

median() { sort -n | awk '{ v[NR] = $1 } END { if (NR) print v[int((NR + 1) / 2)] }'; }

# Each minute's reading from the real bucket counts, with a straight-line estimate inside the bucket. The query count
# comes from the _count series, and a minute under `least` queries is partial, so it is dropped.
minutes() {   # bucket points file, count points file, least
  jq -cs --slurpfile counts "$2" --argjson least "$3" 'group_by(.ts) | map(
    .[0].ts as $ts | ([$counts[] | select(.ts == $ts) | .value] | add // 0) as $n
    | (map(select(.le != "+Inf" and .le != "all") | .le |= tonumber) | sort_by(.le)) as $b
    | ($n * 0.95) as $rank | select($n >= $least and $n > 0)
    | (reduce $b[] as $x ({low: 0, cum: 0, upper: null, p: null};
        if .p != null then .
        elif $x.value >= $rank then .upper = $x.le | .p = (.low + ($x.le - .low) * ($rank - .cum) / (if $x.value > .cum then $x.value - .cum else 1 end))
        else .low = $x.le | .cum = $x.value end)) as $r
    | {ts: $ts, queries: $n, p95_ms: (($r.p // $r.low) * 1000), lower_ms: ($r.low * 1000), upper_ms: (($r.upper // 0) * 1000),
       under: [$b[] | {le_ms: (.le * 1000), share: (.value / $n * 100)}]}) | .[]' "$1" 2>/dev/null
}

# Series by suffix, and by distinct service and query. A new deployment repeats this set once per query per service.
breakdown() {
  duration_series | jq -r '
    [.results[]? | .metric |= sub("^.*duration_?"; "") | .d = .dimensions] as $r
    | ($r | group_by(.metric) | .[] | "  \(if .[0].metric == "" then "(histogram)" else "_" + .[0].metric end): \(length) series"),
      ($r | map([.d["service.name"], .d["db.query.summary"], .d["db.namespace"], .d["server.address"]]) | unique | .[]
        | "  service.name=\(.[0]) db.query.summary=\(.[1]) db.namespace=\(.[2]) server.address=\(.[3])"),
      "  bucket boundaries in Splunk (le): \([$r[] | .d.le // empty] | unique | sort_by(tonumber? // 1e9) | join(", "))",
      "distinct queries per service: \($r | map([.d["service.name"], .d["db.query.summary"], .d["db.namespace"]]) | unique | length)",
      "series per distinct query per service: \(($r | length) / ($r | map([.d["service.name"], .d["db.query.summary"], .d["db.namespace"]]) | unique | length) | floor)"' 2>/dev/null
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.80"
    }
  }
}

locals {
  k8s_version = "1.34"
  node_count  = 2
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ssm_parameter" "ami" {
  name = "/aws/service/eks/optimized-ami/${local.k8s_version}/amazon-linux-2023/x86_64/standard/recommended/image_id"
}

# ---------------- network (public subnets only, no NAT) ----------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = { Name = "${var.lab_name}-vpc" }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "${var.lab_name}-igw" }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true
  tags                    = { Name = "${var.lab_name}-public-${count.index}" }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = { Name = "${var.lab_name}-public" }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------- IAM ----------------
resource "aws_iam_role" "cluster" {
  name                 = "hero-lab-${var.lab_name}-cluster"
  permissions_boundary = var.permissions_boundary
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Action    = "sts:AssumeRole"
      Principal = { Service = "eks.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "cluster" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role" "node" {
  name                 = "hero-lab-${var.lab_name}-node"
  permissions_boundary = var.permissions_boundary
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Action    = "sts:AssumeRole"
      Principal = { Service = "ec2.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "node" {
  for_each = toset([
    "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy",
    "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly",
    "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy",
  ])
  role       = aws_iam_role.node.name
  policy_arn = each.value
}

# The pipeline role only allows IAM resources named hero-lab-*, so the instance profile carries that prefix too.
resource "aws_iam_instance_profile" "node" {
  name = "hero-lab-${var.lab_name}-node"
  role = aws_iam_role.node.name
}

# ---------------- EKS control plane ----------------
resource "aws_eks_cluster" "main" {
  name     = var.lab_name
  role_arn = aws_iam_role.cluster.arn
  version  = local.k8s_version

  vpc_config {
    subnet_ids              = aws_subnet.public[*].id
    endpoint_public_access  = true
    endpoint_private_access = false
  }

  access_config {
    authentication_mode                         = "API"
    bootstrap_cluster_creator_admin_permissions = true
  }

  depends_on = [aws_iam_role_policy_attachment.cluster]
}

resource "aws_eks_access_entry" "node" {
  cluster_name  = aws_eks_cluster.main.name
  principal_arn = aws_iam_role.node.arn
  type          = "EC2_LINUX"
}

# ---------------- self-managed nodes joined with nodeadm ----------------
locals {
  user_data = <<-EOT
    MIME-Version: 1.0
    Content-Type: multipart/mixed; boundary="BOUNDARY"

    --BOUNDARY
    Content-Type: application/node.eks.aws

    ---
    apiVersion: node.eks.aws/v1alpha1
    kind: NodeConfig
    spec:
      cluster:
        name: ${aws_eks_cluster.main.name}
        apiServerEndpoint: ${aws_eks_cluster.main.endpoint}
        certificateAuthority: ${aws_eks_cluster.main.certificate_authority[0].data}
        cidr: ${aws_eks_cluster.main.kubernetes_network_config[0].service_ipv4_cidr}

    --BOUNDARY--
  EOT
}

resource "aws_instance" "node" {
  count                       = local.node_count
  ami                         = nonsensitive(data.aws_ssm_parameter.ami.value)
  instance_type               = "t3.large"
  subnet_id                   = aws_subnet.public[count.index % 2].id
  iam_instance_profile        = aws_iam_instance_profile.node.name
  vpc_security_group_ids      = [aws_eks_cluster.main.vpc_config[0].cluster_security_group_id]
  associate_public_ip_address = true
  user_data                   = local.user_data

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  root_block_device {
    volume_size = 30
    volume_type = "gp3"
  }

  tags = { Name = "${var.lab_name}-node-${count.index}" }

  depends_on = [aws_eks_access_entry.node, aws_iam_role_policy_attachment.node]
}

output "cluster_name" {
  value = aws_eks_cluster.main.name
}
